package com.oguzguven.portfolio.settings;import jakarta.persistence.*;
@Entity @Table(name="site_settings") public class SiteSettings{@Id private Long id=1L;@Column(name="site_name",nullable=false,length=100)private String siteName;@Column(nullable=false,length=120)private String role;@Column(name="browser_title",nullable=false,length=180)private String browserTitle;@Column(name="meta_description",nullable=false,length=500)private String metaDescription;@Column(name="site_language",nullable=false,length=10)private String siteLanguage;@Column(name="display_year",nullable=false,length=10)private String displayYear;@Column(name="projects_year",nullable=false,length=10)private String projectsYear;@Column(name="technology_year",nullable=false,length=10)private String technologyYear;@Column(name="cv_url",length=1000)private String cvUrl;@Column(name="cv_file_name",length=200)private String cvFileName;@Column(name="nav_work_label",nullable=false,length=40)private String navWorkLabel;@Column(name="nav_about_label",nullable=false,length=40)private String navAboutLabel;@Column(name="nav_experience_label",nullable=false,length=40)private String navExperienceLabel;@Column(name="nav_contact_label",nullable=false,length=40)private String navContactLabel;@Column(name="projects_eyebrow",nullable=false,length=80)private String projectsEyebrow;@Column(name="projects_title",nullable=false,length=120)private String projectsTitle;@Column(name="projects_highlight",nullable=false,length=80)private String projectsHighlight;@Column(name="experience_eyebrow",nullable=false,length=80)private String experienceEyebrow;@Column(name="experience_title",nullable=false,length=120)private String experienceTitle;@Column(name="experience_highlight",nullable=false,length=80)private String experienceHighlight;@Column(name="technology_heading",nullable=false,length=100)private String technologyHeading;@Column(name="technology_label",nullable=false,length=100)private String technologyLabel;protected SiteSettings(){}public SiteSettings(SiteSettingsRequest r){update(r);}public void update(SiteSettingsRequest r){siteName=r.siteName();role=r.role();browserTitle=r.browserTitle();metaDescription=r.metaDescription();siteLanguage=r.siteLanguage();displayYear=r.displayYear();projectsYear=r.projectsYear();technologyYear=r.technologyYear();cvUrl=r.cvUrl();cvFileName=r.cvFileName();navWorkLabel=r.navWorkLabel();navAboutLabel=r.navAboutLabel();navExperienceLabel=r.navExperienceLabel();navContactLabel=r.navContactLabel();projectsEyebrow=r.projectsEyebrow();projectsTitle=r.projectsTitle();projectsHighlight=r.projectsHighlight();experienceEyebrow=r.experienceEyebrow();experienceTitle=r.experienceTitle();experienceHighlight=r.experienceHighlight();technologyHeading=r.technologyHeading();technologyLabel=r.technologyLabel();}public String getSiteName(){return siteName;}public String getRole(){return role;}public String getBrowserTitle(){return browserTitle;}public String getMetaDescription(){return metaDescription;}public String getSiteLanguage(){return siteLanguage;}public String getDisplayYear(){return displayYear;}public String getProjectsYear(){return projectsYear;}public String getTechnologyYear(){return technologyYear;}public String getCvUrl(){return cvUrl;}public String getCvFileName(){return cvFileName;}public String getNavWorkLabel(){return navWorkLabel;}public String getNavAboutLabel(){return navAboutLabel;}public String getNavExperienceLabel(){return navExperienceLabel;}public String getNavContactLabel(){return navContactLabel;}public String getProjectsEyebrow(){return projectsEyebrow;}public String getProjectsTitle(){return projectsTitle;}public String getProjectsHighlight(){return projectsHighlight;}public String getExperienceEyebrow(){return experienceEyebrow;}public String getExperienceTitle(){return experienceTitle;}public String getExperienceHighlight(){return experienceHighlight;}public String getTechnologyHeading(){return technologyHeading;}public String getTechnologyLabel(){return technologyLabel;}}
